import{c as a,Q as t,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Terminus-4B: Can a Smaller Model Replace Frontier LLMs at Agentic Execution Tasks?","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.03195","title":"Terminus-4B: Can a Smaller Model Replace Frontier LLMs at Agentic Execution Tasks?","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2605.03195,"authors":["Spandan Garg","Vikram Nitin","Yufan Huang"],"domains":["cs.AI","cs.SE"],"license":"CC BY-NC-ND 4.0","pdf_path":"pdfs/2605.03195.pdf","published_date":"2026-05-04T00:00:00.000Z","tags":["agent","subagent","fine-tuning","SFT","RL","GRPO","token-efficiency","coding-agent","SWE-Bench"]},"headers":[],"relativePath":"research/papers/2026-05-04-terminus-4b-agentic-execution-subagent-2605-03195.md","filePath":"research/papers/2026-05-04-terminus-4b-agentic-execution-subagent-2605-03195.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-04-terminus-4b-agentic-execution-subagent-2605-03195.md"};function r(l,e,s,u,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="terminus-4b-can-a-smaller-model-replace-frontier-llms-at-agentic-execution-tasks" tabindex="-1">Terminus-4B: Can a Smaller Model Replace Frontier LLMs at Agentic Execution Tasks? <a class="header-anchor" href="#terminus-4b-can-a-smaller-model-replace-frontier-llms-at-agentic-execution-tasks" aria-label="Permalink to &quot;Terminus-4B: Can a Smaller Model Replace Frontier LLMs at Agentic Execution Tasks?&quot;">​</a></h1><p><strong>arXiv</strong>: <a href="https://arxiv.org/abs/2605.03195" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.03195</a><strong>Authors</strong>: Spandan Garg, Vikram Nitin, Yufan Huang <strong>Published</strong>: 2026-05-04 | <strong>Archived</strong>: 2026-06-09</p><hr><h2 id="abstract-原文" tabindex="-1">Abstract（原文） <a class="header-anchor" href="#abstract-原文" aria-label="Permalink to &quot;Abstract（原文）&quot;">​</a></h2><blockquote><p>We explore whether fine-tuning a small language model (SLM) can achieve performance comparable to frontier models on agentic terminal execution tasks. We introduce Terminus-4B, a Qwen3-4B model post-trained via supervised fine-tuning (SFT) and reinforcement learning (RL) with a rule-based LLM-judge reward mechanism. Terminus-4B is able to reduce main agent token usage by approximately 30% with no impact on performance compared to a no-subagent baseline. We conduct extensive evaluation across multiple frontier models, training ablations, and main agent configurations, demonstrating the practical potential of smaller, specialized models for agentic execution subtasks.</p></blockquote><p><strong>中文說明</strong>：研究核心問題是「4B 小模型能否在代理終端執行任務上媲美前沿模型」。答案是肯定的：Terminus-4B 透過 SFT + RL 訓練後，能讓主代理節省約 30% token，且不影響問題解決率。</p><hr><h2 id="_1-introduction-原文摘錄" tabindex="-1">1. Introduction（原文摘錄） <a class="header-anchor" href="#_1-introduction-原文摘錄" aria-label="Permalink to &quot;1. Introduction（原文摘錄）&quot;">​</a></h2><blockquote><p>&quot;Terminal output is often the single largest consumer of context in coding agent trajectories,&quot; causing agents to waste tokens processing verbose build logs and test results that could be summarized concisely.</p></blockquote><blockquote><p>Modern coding agents delegate specialized subtasks to smaller, focused agent loops. These subagents handle narrow responsibilities such as search, debugging, or terminal execution.</p></blockquote><p><strong>中文說明</strong>：終端輸出（build log、測試結果）是 coding agent context 最大的消耗源。現代架構趨勢是將此類子任務委派給更小的專門代理——這是本論文的切入點。</p><hr><h2 id="_2-solution-architecture-原文" tabindex="-1">2. Solution Architecture（原文） <a class="header-anchor" href="#_2-solution-architecture-原文" aria-label="Permalink to &quot;2. Solution Architecture（原文）&quot;">​</a></h2><p>The execution subagent is configured with:</p><ul><li>Single Terminal tool access</li><li>10-turn limit (configurable)</li><li>Structured XML-format responses</li><li>System prompt enforcing concise summaries</li></ul><p><strong>中文說明</strong>：子代理設計極簡：只給一個 Terminal tool、限 10 輪、強制 XML 格式輸出摘要。這種約束設計讓主代理收到的是壓縮過的結果，而非原始終端噪音。</p><hr><h2 id="_3-training-pipeline-原文" tabindex="-1">3. Training Pipeline（原文） <a class="header-anchor" href="#_3-training-pipeline-原文" aria-label="Permalink to &quot;3. Training Pipeline（原文）&quot;">​</a></h2><h3 id="phase-1-supervised-fine-tuning" tabindex="-1">Phase 1: Supervised Fine-Tuning <a class="header-anchor" href="#phase-1-supervised-fine-tuning" aria-label="Permalink to &quot;Phase 1: Supervised Fine-Tuning&quot;">​</a></h3><ul><li>Dataset: ~3,200 execution tasks across 730 GitHub repositories</li><li>Languages: TypeScript (36.5%), C# (27.8%), Java (26.2%), JavaScript (7.1%), Python (2.3%)</li><li>Method: Standard language modeling loss on assistant tokens only</li><li>Duration: 2 epochs with peak learning rate of 2×10⁻⁵</li></ul><h3 id="phase-2-reinforcement-learning" tabindex="-1">Phase 2: Reinforcement Learning <a class="header-anchor" href="#phase-2-reinforcement-learning" aria-label="Permalink to &quot;Phase 2: Reinforcement Learning&quot;">​</a></h3><ul><li>Algorithm: Group Relative Policy Optimization (GRPO)</li><li>Reward Design: Multi-dimensional rubric-based LLM-as-judge scoring: <ul><li>7 execution quality dimensions</li><li>4 failure mode dimensions</li><li>3 final-answer quality dimensions</li></ul></li><li>Formula: <code>r = (1-α)(s̄pos - s̄pit) + α·s̄fa</code>, where α=0.5</li></ul><h3 id="key-innovation-subagent-rollout-framework" tabindex="-1">Key Innovation: Subagent Rollout Framework <a class="header-anchor" href="#key-innovation-subagent-rollout-framework" aria-label="Permalink to &quot;Key Innovation: Subagent Rollout Framework&quot;">​</a></h3><blockquote><p>Researchers decoupled the subagent from the main agent during training by using a lightweight pass-through model as the main agent, ensuring deterministic query forwarding, running rollouts in isolated Docker containers, and eliminating frontier LLM costs during training.</p></blockquote><p><strong>中文說明</strong>：</p><ul><li><strong>SFT 階段</strong>：約 3,200 筆執行任務資料，覆蓋 730 個 GitHub repo，以多語言（TypeScript/C#/Java 為主）訓練。</li><li><strong>RL 階段</strong>：採 GRPO 演算法，獎勵函數由 LLM-as-judge 評分（14 個維度），兼顧執行品質與避免失敗模式。</li><li><strong>關鍵創新</strong>：訓練時用輕量 pass-through 模型替代前沿 LLM 作主代理，在 Docker 容器隔離執行 rollout，大幅降低訓練成本。</li></ul><hr><h2 id="_4-results-原文" tabindex="-1">4. Results（原文） <a class="header-anchor" href="#_4-results-原文" aria-label="Permalink to &quot;4. Results（原文）&quot;">​</a></h2><h3 id="swe-bench-pro-multi-language" tabindex="-1">SWE-Bench Pro (Multi-language) <a class="header-anchor" href="#swe-bench-pro-multi-language" aria-label="Permalink to &quot;SWE-Bench Pro (Multi-language)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Configuration</th><th>Resolution Rate</th><th>Token Change</th></tr></thead><tbody><tr><td>No Subagent</td><td>30.0%</td><td>baseline</td></tr><tr><td>Opus Subagent</td><td>32.0%</td><td>-10.5%</td></tr><tr><td>Vanilla-4B</td><td>30.4%</td><td>+0.5%</td></tr><tr><td>SFT-4B</td><td>32.4%</td><td>-13.0%</td></tr><tr><td><strong>Terminus-4B</strong></td><td><strong>31.5%</strong></td><td><strong>-12.7%</strong></td></tr></tbody></table><ul><li>Main Agent Terminal Calls: Reduced from 3.8 to 1.0 (~74% reduction)</li><li>Subagent→Terminal Rate: 14% (vs. 27% for vanilla model)</li></ul><h3 id="swe-bench-c-internal-benchmark-claude-opus-4-6-as-main-agent" tabindex="-1">SWE-Bench C# (Internal Benchmark, Claude Opus 4.6 as main agent) <a class="header-anchor" href="#swe-bench-c-internal-benchmark-claude-opus-4-6-as-main-agent" aria-label="Permalink to &quot;SWE-Bench C# (Internal Benchmark, Claude Opus 4.6 as main agent)&quot;">​</a></h3><ul><li>Token Efficiency: Up to 31.4% reduction in main agent tokens</li><li>Resolution Rate: 46.7% (matched baseline)</li><li>Main Terminal Calls: Reduced from 6.2 to 1.7 calls</li><li>Subagent→Subagent Distrust: 0.23 (matching frontier models)</li></ul><h3 id="no-terminal-ablation" tabindex="-1">No-Terminal Ablation <a class="header-anchor" href="#no-terminal-ablation" aria-label="Permalink to &quot;No-Terminal Ablation&quot;">​</a></h3><blockquote><p>When Terminal tool removed entirely: Resolution 45.9% (comparable to Opus baseline of 45.3%), 18.2% frontier token reduction vs. Opus subagent, Subagent Repeat Rate 0.89 (matching Opus at 0.89).</p></blockquote><h3 id="cross-model-generalization" tabindex="-1">Cross-Model Generalization <a class="header-anchor" href="#cross-model-generalization" aria-label="Permalink to &quot;Cross-Model Generalization&quot;">​</a></h3><p>Tested with three main agent models (Claude Opus, Sonnet, GPT-5.3-Codex):</p><ul><li>Consistent token savings: 17–32% reduction</li><li>Stable resolution rates across all configurations</li><li>Terminal usage reduction: 62–79%</li></ul><h3 id="llm-judge-evaluation" tabindex="-1">LLM-Judge Evaluation <a class="header-anchor" href="#llm-judge-evaluation" aria-label="Permalink to &quot;LLM-Judge Evaluation&quot;">​</a></h3><p>Terminus-4B achieved comparable quality scores to frontier models across 5 dimensions: task completion, factual accuracy, informativeness, relevance, actionability.</p><p><strong>中文說明</strong>：</p><ul><li>SWE-Bench Pro：Terminus-4B 解決率 31.5% 略低於 SFT-4B（32.4%），但 token 節省幾乎相同（-12.7% vs -13.0%）。重要的是主代理 Terminal 呼叫從 3.8 降至 1.0，代表主代理的「注意力」更集中。</li><li>SWE-Bench C#：使用 Claude Opus 4.6 作主代理，token 節省達 31.4%，解決率維持 46.7%。</li><li>跨模型泛化：三個主代理（Opus/Sonnet/GPT-5.3-Codex）皆有穩定的 17–32% token 節省，證明子代理本身的設計是可遷移的。</li></ul><hr><h2 id="_5-real-world-impact-example-原文" tabindex="-1">5. Real-World Impact Example（原文） <a class="header-anchor" href="#_5-real-world-impact-example-原文" aria-label="Permalink to &quot;5. Real-World Impact Example（原文）&quot;">​</a></h2><blockquote><p>A Serilog C# issue:</p><ul><li>Baseline: 2.46M main agent tokens across 40 turns with 18 direct terminal calls</li><li>With Terminus-4B: 740k main agent tokens across 32 turns with subagent handling</li><li>Result: ~70% token reduction, cleaner context window</li></ul></blockquote><p><strong>中文說明</strong>：單一真實案例中 token 消耗從 2.46M 降至 740k（減少約 70%），同時輪次從 40 降至 32。這說明子代理不只是節省 token，也讓主代理的推理鏈更乾淨。</p><hr><h2 id="_6-limitations-原文" tabindex="-1">6. Limitations（原文） <a class="header-anchor" href="#_6-limitations-原文" aria-label="Permalink to &quot;6. Limitations（原文）&quot;">​</a></h2><ul><li>Unix/Bash-focused; limited Windows PowerShell/Command Prompt support</li><li>Evaluation limited to SWE-Bench style benchmarks</li><li>Only trained on Qwen3-4B; unclear transfer to other model families</li><li>May not reflect real-world deployment complexity</li></ul><p><strong>中文說明</strong>：主要限制是平台偏（Unix/Bash）、基準單一（SWE-Bench 風格）、模型族群遷移性未知。實際部署複雜度可能超出論文評估範圍。</p><hr><h2 id="_7-conclusion-原文" tabindex="-1">7. Conclusion（原文） <a class="header-anchor" href="#_7-conclusion-原文" aria-label="Permalink to &quot;7. Conclusion（原文）&quot;">​</a></h2><blockquote><p>&quot;Terminus-4B not only closes the gap between the Vanilla Qwen model and frontier models like Claude Sonnet/Opus/GPT-5.3-Codex, but often even exceeds their performance&quot; while enabling up to 30% token reduction for main agents. The approach demonstrates that smaller, specialized models can effectively replace frontier LLMs for narrowly-scoped agentic subtasks.</p></blockquote><p><strong>中文說明</strong>：核心結論是「範疇明確的子任務可以用小模型替代前沿 LLM」。這個方向對降低 agent 系統成本有直接意義——不需要在每個子任務都呼叫大模型。</p><hr><h2 id="workspace-相關性" tabindex="-1">Workspace 相關性 <a class="header-anchor" href="#workspace-相關性" aria-label="Permalink to &quot;Workspace 相關性&quot;">​</a></h2><ul><li><strong>Sub-agent 策略</strong>：印證 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的「任務分類先於委派」——終端執行是典型 on-rails 任務，委派給專門小模型合理</li><li><strong>Token 預算</strong>：30% 主代理 token 節省與 <code>context-management.md</code> 的 per-task budget 直接相關</li><li><strong>訓練方法</strong>：GRPO + LLM-as-judge 可作為 workspace eval 設計參考（對照 <code>refs/harness-meta</code>）</li></ul>',57)])])}const m=a(o,[["render",r]]);export{g as __pageData,m as default};
